const raw = ($json.body?.message || '').trim();
const query = raw.replace(/^(cari buku|buku|karya|novel|author|search)\s*/i, '').replace(/^["']|["']$/g, '').trim() || 'Dune';
return { json: { query, searchUrl: `https://openlibrary.org/search.json?q=${encodeURIComponent(query)}&limit=4` } };

const docs = $json.docs || [];
if (docs.length === 0) {
  return { json: { content: '📚 Buku tidak ditemukan di katalog Open Library.', chips: ['🔍 Cari Buku "Harry Potter"', '🔍 Cari Buku "Dune"'] } };
}
const b = docs[0];
const author = b.author_name ? b.author_name.join(', ') : 'Unknown';
let content = `📚 **[KATALOG OPEN LIBRARY: ${b.title}]**\n\n`;
content += `- **Penulis:** ✍️ **${author}**\n`;
content += `- **Tahun Terbit:** 🗓️ **${b.first_publish_year || 'N/A'}**\n`;
content += `- **Total Edisi:** 📑 **${b.edition_count || 1} edisi**\n\n`;
if (b.cover_i) {
  content += `🖼️ **Cover:** [Lihat Cover](${`https://covers.openlibrary.org/b/id/${b.cover_i}-M.jpg`})\n\n`;
}
const chips = ['🔍 Cari Buku "Harry Potter"', '🔍 Cari Buku "The Hobbit"', '🔍 Cari Buku "1984"', '📖 Rekomendasi Sci-Fi'];
return { json: { content, chips } };
